#!/usr/bin/env bash
set -euo pipefail

# run-u-end-to-end.sh TARGET QUERIES OUT [--tree DIR] [--build DIR]\n#                       [--drop-opcode OP] [--allow-unanswerable N]
#
# U side: the queries were generated by the oracle from the *upstream* rules
# (`scripts/oracle/gen-u.sh`), not by gisel.  Both implementations answer the
# same file: the official runner from the pinned library, ours from the
# generated include.  This is the direction that proves gisel does not miss an
# upstream rule.
#
#   TARGET   x86 | aarch64 | riscv | arm | mips | ppc | m68k | wasm | spirv
#   QUERIES  queries.jsonl from gen-u.sh
#   OUT      artifacts (runners, answers, diff.json, attribution.json)
#
# Environment:
#   AB_TREE / AB_BUILD   pinned checkout and build (required)
#   U_INC                generated include; if unset it is built from the
#                        corpus with `gisel gen --emit=inc`
#
# --drop-opcode OP runs the negative control: OP's rules are replaced with
# `.unsupported()` in the include, and the run passes only if the diff sees
# disagreements and every one of them is attributed to that builder's rulesets.
#
# --allow-ref-asserts pins the queries where the *reference* asserts before
# answering and ours answers (diff.py's `ref_asserted` class).  They are
# upstream defects in the query's own type, not a rule translation gap.
# `N` pins the total; `file:line=count,...` or `@file.json` pins each assert
# site, so a new assert class cannot hide behind an unchanged total.
#
# The diff always compares where the two sides died (`--assert-sites`).  A site
# difference is provenance, not an answer difference, so it is reported and
# does not change the exit code; but a run that cannot say "both sides assert
# at the same place" has not explained its unanswerable count.
TARGET=${1:?usage: run-u-end-to-end.sh TARGET QUERIES OUT [--tree DIR] [--build DIR]}
QUERIES=${2:?}
OUT=${3:?}
shift 3
DROP=""
ALLOW_UNANSWERABLE=0
ALLOW_REF_ASSERTS=""
TREE_ARG=""
BUILD_ARG=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --tree) TREE_ARG=${2:?}; shift 2 ;;
    --build) BUILD_ARG=${2:?}; shift 2 ;;
    --drop-opcode) DROP=${2:?}; shift 2 ;;
    --allow-unanswerable) ALLOW_UNANSWERABLE=${2:?}; shift 2 ;;
    --allow-ref-asserts) ALLOW_REF_ASSERTS=${2:?}; shift 2 ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
done

AB_ROOT=${AB_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)}
. "$AB_ROOT/scripts/lib.sh"
TREE=${TREE_ARG:-${AB_TREE:-}}
BUILD=${BUILD_ARG:-${AB_BUILD:-}}
require_roots "$TREE" "$BUILD" || exit 2
mkdir -p "$OUT"

if ! python3 -m gisel_ab.targets env "$TARGET" >/dev/null 2>&1; then
  echo "unsupported target: $TARGET" >&2
  exit 2
fi
eval "$(python3 -m gisel_ab.targets env "$TARGET")"
CORPUS=$GISEL/$T_SOURCE
BUILDER=$T_U_BUILDER
INC_NAME=$T_INC_NAME

if [[ ! -f $QUERIES ]]; then
  echo "input error: queries not found: $QUERIES" >&2
  exit 2
fi

if [[ -n ${U_INC:-} ]]; then
  BASE_INC=$U_INC
else
  BASE_INC=$OUT/$INC_NAME
  if ! python3 -m gisel gen "$CORPUS" --emit=inc --out "$BASE_INC" >/dev/null; then
    echo "input error: gisel gen failed for $CORPUS" >&2
    exit 2
  fi
fi
if [[ ! -s $BASE_INC ]]; then
  echo "input error: include not found or empty: $BASE_INC" >&2
  exit 2
fi

OURS_INC=$BASE_INC
EXPECT=""
if [[ -n $DROP ]]; then
  OURS_INC=$OUT/$INC_NAME.injected
  EXPECT=$OUT/expected-rulesets.json
  if ! python3 -m gisel_ab.l0.inject_opcode "$BASE_INC" "$DROP" \
      "$OURS_INC" --expect "$EXPECT" >/dev/null; then
    echo "input error: could not inject $DROP into $BASE_INC" >&2
    exit 2
  fi
  if [[ ! -s $OURS_INC || ! -s $EXPECT ]]; then
    echo "input error: missing injected include or expectation" >&2
    exit 2
  fi
fi

echo "[1/4] build runners ($TARGET${DROP:+, drop $DROP})" >&2
"$BUILDER" "$TREE" "$BUILD" "$OURS_INC" "$OUT/runner"

echo "[2/4] answer: official" >&2
python3 -m gisel_ab.l0.queries "$OUT/runner.official" "$QUERIES" \
  "$OUT/official.answers.jsonl"

echo "[3/4] answer: ours" >&2
python3 -m gisel_ab.l0.queries "$OUT/runner.ours" "$QUERIES" \
  "$OUT/ours.answers.jsonl"

echo "[4/4] diff + attribution" >&2
set +e
DIFF_ARGS=(--json --details 200000 --assert-sites)
if [[ -n $ALLOW_REF_ASSERTS ]]; then
  DIFF_ARGS+=(--allow-ref-asserts "$ALLOW_REF_ASSERTS")
fi
python3 -m gisel_ab.l0.diff "$OUT/official.answers.jsonl" \
  "$OUT/ours.answers.jsonl" --queries "$QUERIES" \
  "${DIFF_ARGS[@]}" > "$OUT/diff.json"
DIFF_RC=$?
set -e
if [[ $DIFF_RC -ne 0 && $DIFF_RC -ne 1 ]]; then
  echo "input error: diff rc=$DIFF_RC; see $OUT/diff.json" >&2
  exit 2
fi

set +e
python3 -m gisel_ab.l0.u_attribution --diff "$OUT/diff.json" \
  --queries "$QUERIES" --json ${EXPECT:+--expect "$EXPECT"} \
  | tee "$OUT/attribution.json"
ATTR_RC=${PIPESTATUS[0]}
set -e

UNANS=$(python3 -c "import json,sys; print(json.load(open(sys.argv[1]))['unanswerable'])" "$OUT/diff.json")
echo "diff_rc=$DIFF_RC unanswerable=$UNANS attr_rc=$ATTR_RC" >&2

if [[ $ATTR_RC -eq 2 ]]; then
  echo "input error: attribution could not read its inputs" >&2
  exit 2
fi

if [[ -n $DROP ]]; then
  if [[ $ATTR_RC -ne 0 ]]; then
    echo "negative control: disagreements were not attributed to $DROP" >&2
    exit 1
  fi
  classify_negative_rc "$DIFF_RC" "u-negative $TARGET $DROP" || exit $?
  exit 0
fi

if [[ $DIFF_RC -ne 0 ]]; then
  echo "U side disagrees (see $OUT/diff.json)" >&2
  exit 1
fi
if [[ "$UNANS" -gt "$ALLOW_UNANSWERABLE" ]]; then
  echo "$UNANS queries unanswerable, allowed $ALLOW_UNANSWERABLE" >&2
  exit 1
fi
